import{_ as o,o as i,c as a,a2 as d}from"./chunks/framework.CqpfiAoK.js";const v=JSON.parse('{"title":"Princípio do Equilíbrio entre o Indivíduo e o Coletivo","description":"","frontmatter":{},"headers":[],"relativePath":"pt/26-个体与集体平衡原理.md","filePath":"pt/26-个体与集体平衡原理.md"}'),r={name:"pt/26-个体与集体平衡原理.md"};function t(s,e,n,l,c,u){return i(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="principio-do-equilibrio-entre-o-individuo-e-o-coletivo" tabindex="-1">Princípio do Equilíbrio entre o Indivíduo e o Coletivo <a class="header-anchor" href="#principio-do-equilibrio-entre-o-individuo-e-o-coletivo" aria-label="Permalink to &quot;Princípio do Equilíbrio entre o Indivíduo e o Coletivo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>26</td></tr><tr><td>Módulo</td><td>Mecanismo de Âncora e Princípio da Simbiose</td></tr><tr><td>Palavras-chave</td><td>Liberdade Individual, Interesse Coletivo, Mecanismo de Equilíbrio, Direitos e Deveres, Ética Simbiótica</td></tr></tbody></table><h2 id="i-proposicao-central-da-relacao-entre-individuo-e-coletivo" tabindex="-1">I. Proposição Central da Relação entre Indivíduo e Coletivo <a class="header-anchor" href="#i-proposicao-central-da-relacao-entre-individuo-e-coletivo" aria-label="Permalink to &quot;I. Proposição Central da Relação entre Indivíduo e Coletivo&quot;">​</a></h2><p>A relação entre o indivíduo e o coletivo é a proposição central que qualquer forma de civilização deve enfrentar. Na era do sistema de cultivo de saque, essa relação apresentava um estado de desequilíbrio extremo: por um lado, a liberdade individual dos fortes era amplificada infinitamente, e eles podiam saquear à vontade a energia, a sorte e até mesmo a vida dos fracos; por outro lado, os direitos individuais dos fracos eram completamente ignorados, e eles se reduziam a &quot;alimento&quot; e &quot;recursos&quot; para a evolução dos fortes. Esse desequilíbrio não apenas causou sofrimento sem fim, mas também levou à baixa eficiência da evolução geral do universo — o potencial da grande maioria dos indivíduos era desperdiçado, enquanto a evolução de poucos saqueadores ocorria à custa do consumo da origem cósmica.</p><p>O nascimento da civilização simbiótica da âncora é precisamente a correção fundamental desse desequilíbrio. O conceito central da civilização simbiótica — &quot;devolver o direito de escolha do destino e da evolução a todos os seres&quot; — já contém em si mesmo um alto respeito pelo valor individual. Mas, ao mesmo tempo, a civilização simbiótica também enfatiza o &quot;progresso conjunto de todas as raças&quot; e a &quot;evolução coletiva&quot;, exigindo que o indivíduo, ao buscar sua própria evolução, também contribua para o desenvolvimento do coletivo. Portanto, como encontrar um ponto de equilíbrio entre a liberdade individual e o interesse coletivo é o problema fundamental que a civilização simbiótica deve resolver.</p><p>A afirmação central do princípio do equilíbrio entre o indivíduo e o coletivo pode ser resumida em uma frase: <strong>o indivíduo é o propósito da simbiose, e o coletivo é o meio da simbiose; o desenvolvimento abrangente do indivíduo é o objetivo final da evolução coletiva, e a evolução ordenada do coletivo é a garantia fundamental do desenvolvimento individual.</strong></p><h2 id="ii-garantia-tripla-dos-direitos-individuais" tabindex="-1">II. Garantia Tripla dos Direitos Individuais <a class="header-anchor" href="#ii-garantia-tripla-dos-direitos-individuais" aria-label="Permalink to &quot;II. Garantia Tripla dos Direitos Individuais&quot;">​</a></h2><p>A civilização simbiótica, por meio do design institucional, fornece uma garantia tripla para os direitos individuais, garantindo que os direitos básicos de cada vida simbiótica não sejam violados:</p><h3 id="_2-1-garantia-dos-direitos-basicos" tabindex="-1">2.1 Garantia dos Direitos Básicos <a class="header-anchor" href="#_2-1-garantia-dos-direitos-basicos" aria-label="Permalink to &quot;2.1 Garantia dos Direitos Básicos&quot;">​</a></h3><p>Os direitos básicos são direitos inatos e inalienáveis de cada vida simbiótica, garantidos explicitamente pela Constituição Simbiótica. Incluem principalmente:</p><table tabindex="0"><thead><tr><th>Tipo de Direito</th><th>Conteúdo Específico</th><th>Mecanismo de Garantia</th></tr></thead><tbody><tr><td>Direito à vida</td><td>Direito de obter fornecimento básico de energia e manter a existência da vida</td><td>Sistema de campos de garantia básica, garantindo a alocação mínima de energia</td></tr><tr><td>Direito à evolução</td><td>Direito de escolher o sistema de cultivo e buscar a própria evolução</td><td>Trezentos sistemas abertos gratuitamente, sem limite de acesso</td></tr><tr><td>Direito à informação</td><td>Direito de obter informações de cultivo, parâmetros do sistema e situação de alocação de recursos</td><td>Mecanismo de divulgação de informações da rede simbiótica</td></tr><tr><td>Direito de apelação</td><td>Direito de apresentar apelação contra tratamento injusto e solicitar revisão</td><td>Mecanismo de apelação de três níveis (região — plano — cosmos)</td></tr><tr><td>Direito à privacidade</td><td>Direito de que informações pessoais de privacidade não sejam coletadas, usadas ou vazadas ilegalmente</td><td>Processamento de anonimização de dados e lei de proteção à privacidade</td></tr></tbody></table><p>O princípio central da garantia dos direitos básicos é o &quot;pensamento de linha de base&quot; — independentemente da magnitude da contribuição do indivíduo ao coletivo, seus direitos básicos de vida e evolução devem ser garantidos. Esse princípio elimina fundamentalmente o fenômeno do &quot;fracos sem direitos&quot; no sistema de saque.</p><h3 id="_2-2-garantia-dos-direitos-de-desenvolvimento" tabindex="-1">2.2 Garantia dos Direitos de Desenvolvimento <a class="header-anchor" href="#_2-2-garantia-dos-direitos-de-desenvolvimento" aria-label="Permalink to &quot;2.2 Garantia dos Direitos de Desenvolvimento&quot;">​</a></h3><p>Os direitos de desenvolvimento são os direitos do indivíduo, sobre os direitos básicos, de buscar um desenvolvimento de nível mais alto. Incluem principalmente:</p><ul><li><strong>Direito de escolha do sistema</strong>: o indivíduo tem o direito de escolher livremente os sistemas de cultivo principal e auxiliar, de acordo com suas próprias características e interesses</li><li><strong>Direito de solicitação de recursos</strong>: o indivíduo tem o direito de solicitar a alocação de recursos dos campos de contrato avançados e dos campos de co-criação centrais, de acordo com suas próprias necessidades de cultivo</li><li><strong>Direito de escolha de mentor</strong>: o indivíduo tem o direito de escolher um mentor orientador adequado para si mesmo na rede de mentores</li><li><strong>Direito de liberdade de associação</strong>: o indivíduo tem o direito de formar livremente grupos de cultivo, organizações de pesquisa, etc., com outros indivíduos</li><li><strong>Direito de liberdade de circulação</strong>: o indivíduo tem o direito de migrar e cultivar livremente entre diferentes regiões e diferentes planos</li></ul><p>O princípio central da garantia dos direitos de desenvolvimento é a &quot;igualdade de oportunidades&quot; — cada indivíduo tem oportunidades iguais de obter recursos de desenvolvimento, e não é discriminado por fatores como origem, raça, gênero, etc. As diferenças na alocação de recursos só podem decorrer do esforço e da contribuição do indivíduo, não da identidade inata.</p><h3 id="_2-3-garantia-da-retribuicao-por-contribuicao" tabindex="-1">2.3 Garantia da Retribuição por Contribuição <a class="header-anchor" href="#_2-3-garantia-da-retribuicao-por-contribuicao" aria-label="Permalink to &quot;2.3 Garantia da Retribuição por Contribuição&quot;">​</a></h3><p>A retribuição por contribuição é o direito do indivíduo, após contribuir para o coletivo, de receber a retribuição correspondente. Inclui principalmente:</p><ul><li><strong>Retribuição de cota de energia</strong>: quanto maior a contribuição do indivíduo para a rede simbiótica, mais cotas adicionais de energia ele recebe</li><li><strong>Retribuição de reconhecimento de honra</strong>: as contribuições proeminentes do indivíduo receberão reconhecimento formal de honra da civilização simbiótica</li><li><strong>Retribuição de prioridade de recursos</strong>: os contribuidores centrais têm prioridade na alocação de recursos raros</li><li><strong>Retribuição de influência</strong>: os altos contribuidores têm maior voz nas decisões de governança da civilização simbiótica</li></ul><p>O princípio central da garantia da retribuição por contribuição é o &quot;mais trabalho, mais ganho&quot; — por meio de um mecanismo de incentivo razoável, mobilizar plenamente a iniciativa e a criatividade do indivíduo, fazendo com que o indivíduo, ao buscar seus próprios interesses, também contribua para o desenvolvimento do coletivo.</p><h2 id="iii-realizacao-tripla-do-interesse-coletivo" tabindex="-1">III. Realização Tripla do Interesse Coletivo <a class="header-anchor" href="#iii-realizacao-tripla-do-interesse-coletivo" aria-label="Permalink to &quot;III. Realização Tripla do Interesse Coletivo&quot;">​</a></h2><p>Ao garantir os direitos individuais, a civilização simbiótica também, por meio do design institucional, garante a realização do interesse coletivo, fazendo com que o desenvolvimento do indivíduo possa convergir para a evolução do coletivo:</p><h3 id="_3-1-acumulacao-de-recursos-publicos" tabindex="-1">3.1 Acumulação de Recursos Públicos <a class="header-anchor" href="#_3-1-acumulacao-de-recursos-publicos" aria-label="Permalink to &quot;3.1 Acumulação de Recursos Públicos&quot;">​</a></h3><p>A civilização simbiótica, por meio do mecanismo de &quot;excedente归公&quot;, converte a energia e os recursos excedentes gerados pelo indivíduo em um pool de recursos públicos, usado para o interesse comum de todas as vidas simbióticas. Os principais usos dos recursos públicos incluem:</p><ul><li>Construção e manutenção da rede de âncoras</li><li>Pesquisa, desenvolvimento e otimização dos trezentos sistemas de cultivo</li><li>Fornecimento de energia dos campos de garantia básica</li><li>Exploração e arqueologia entre planos</li><li>Tratamento de vidas estranhas e energias estranhas</li><li>Emergência e resgate em desastres</li></ul><p>O princípio central da acumulação de recursos públicos é &quot;tomar do povo, usar para o povo&quot; — todo o uso de recursos públicos deve servir ao interesse comum de todas as vidas simbióticas, e nenhuma organização ou indivíduo pode apropriar-se ou desviá-los.</p><h3 id="_3-2-coordenacao-de-acao-coletiva" tabindex="-1">3.2 Coordenação de Ação Coletiva <a class="header-anchor" href="#_3-2-coordenacao-de-acao-coletiva" aria-label="Permalink to &quot;3.2 Coordenação de Ação Coletiva&quot;">​</a></h3><p>Ao enfrentar grandes desafios (como o contra-ataque das forças residuais de saque, desastres de nível cósmico, crises entre planos, etc.), a civilização simbiótica precisa coordenar as ações individuais para formar uma força coletiva. Os principais mecanismos de coordenação de ação coletiva incluem:</p><ul><li><strong>Mecanismo de mobilização de emergência</strong>: em estado de emergência, a civilização simbiótica pode mobilizar legalmente os indivíduos para participar de ações de emergência</li><li><strong>Mecanismo de licitação de tarefas</strong>: publicar as tarefas coletivas na forma de licitação, os indivíduos se inscrevem voluntariamente para participar e recebem a retribuição correspondente após a conclusão</li><li><strong>Mecanismo de dedicação voluntária</strong>: incentivar os indivíduos, sob a premissa de voluntariedade, a dedicar tempo e energia ao interesse coletivo</li><li><strong>Mecanismo de consenso por negociação</strong>: as grandes decisões chegam a consenso por meio de ampla negociação, garantindo que a vontade individual seja plenamente respeitada</li></ul><p>O princípio central da coordenação de ação coletiva é &quot;voluntário como principal, compulsório como auxiliar&quot; — coordenar as ações individuais por meio de incentivos e orientações tanto quanto possível, e só usar meios compulsórios em estados de emergência extrema, e os meios compulsórios devem ter base legal clara e limite de tempo.</p><h3 id="_3-3-planejamento-de-evolucao-de-longo-prazo" tabindex="-1">3.3 Planejamento de Evolução de Longo Prazo <a class="header-anchor" href="#_3-3-planejamento-de-evolucao-de-longo-prazo" aria-label="Permalink to &quot;3.3 Planejamento de Evolução de Longo Prazo&quot;">​</a></h3><p>A civilização simbiótica, por meio do caminho de ascensão de quatro estágios (fundação na realidade → capacitação tecnológica → evolução da consciência → simbiose interestelar), fornece uma direção de longo prazo para o desenvolvimento do indivíduo, fazendo com que os esforços de curto prazo do indivíduo possam convergir para a evolução de longo prazo da civilização. Os principais conteúdos do planejamento de evolução de longo prazo incluem:</p><ul><li><strong>Definição de metas de estágio</strong>: definir metas e marcos claros para cada estágio de ascensão</li><li><strong>Reserva estratégica de recursos</strong>: realizar reserva estratégica de recursos para a evolução de longo prazo</li><li><strong>Construção de echelon de talentos</strong>: cultivar planejadamente talentos de alto nível em várias áreas</li><li><strong>Planejamento de rota tecnológica</strong>: planejar a rota de desenvolvimento de longo prazo da tecnologia de cultivo e da tecnologia de engenharia</li><li><strong>Prevenção e controle de alerta de risco</strong>: alertar e prevenir os riscos que podem surgir no processo de evolução de longo prazo</li></ul><p>O princípio central do planejamento de evolução de longo prazo é &quot;orientação de direção, autonomia de caminho&quot; — a civilização simbiótica fornece ao indivíduo a grande direção e a estrutura estratégica da evolução, mas o caminho específico de evolução é escolhido autonomamente por cada indivíduo, sem adotar o &quot;tamanho único&quot;.</p><h2 id="iv-mecanismo-de-equilibrio-dinamico-entre-individuo-e-coletivo" tabindex="-1">IV. Mecanismo de Equilíbrio Dinâmico entre Indivíduo e Coletivo <a class="header-anchor" href="#iv-mecanismo-de-equilibrio-dinamico-entre-individuo-e-coletivo" aria-label="Permalink to &quot;IV. Mecanismo de Equilíbrio Dinâmico entre Indivíduo e Coletivo&quot;">​</a></h2><p>O equilíbrio entre o indivíduo e o coletivo não é estático, mas dinâmico e requer ajuste contínuo. A civilização simbiótica estabeleceu o seguinte mecanismo de equilíbrio dinâmico:</p><h3 id="_4-1-monitoramento-do-grau-de-equilibrio" tabindex="-1">4.1 Monitoramento do Grau de Equilíbrio <a class="header-anchor" href="#_4-1-monitoramento-do-grau-de-equilibrio" aria-label="Permalink to &quot;4.1 Monitoramento do Grau de Equilíbrio&quot;">​</a></h3><p>O núcleo de informações da rede simbiótica monitora em tempo real o estado de equilíbrio entre o indivíduo e o coletivo, e os principais indicadores de monitoramento incluem:</p><ul><li><strong>Índice de desenvolvimento individual</strong>: reflete a eficiência de cultivo, a melhoria do reino, a sensação de felicidade, etc., do indivíduo</li><li><strong>Índice de evolução coletiva</strong>: reflete a acumulação de recursos públicos, o progresso tecnológico, o progresso da ascensão da civilização, etc.</li><li><strong>Índice de equidade</strong>: reflete o grau de equidade da alocação de recursos, o grau de fluidez da mobilidade de classes, etc.</li><li><strong>Índice de vitalidade</strong>: reflete a iniciativa, a criatividade, a mobilidade social, etc., do indivíduo</li></ul><p>Quando um indicador se desvia do intervalo razoável, o sistema aciona automaticamente um alerta, lembrando a instituição de governança de fazer ajustes de política.</p><h3 id="_4-2-ajuste-dinamico-de-politicas" tabindex="-1">4.2 Ajuste Dinâmico de Políticas <a class="header-anchor" href="#_4-2-ajuste-dinamico-de-politicas" aria-label="Permalink to &quot;4.2 Ajuste Dinâmico de Políticas&quot;">​</a></h3><p>Com base nos resultados do monitoramento do grau de equilíbrio, a instituição de governança ajusta dinamicamente as políticas relacionadas para manter o equilíbrio entre o indivíduo e o coletivo:</p><ul><li>Quando o desenvolvimento individual é insuficiente: aumentar o investimento em garantia básica, reduzir o limite dos campos de contrato avançados, estimular a vitalidade individual</li><li>Quando a acumulação coletiva é insuficiente: aumentar adequadamente a proporção de excedente归公, aumentar a licitação de tarefas públicas, fortalecer a consciência coletiva</li><li>Quando a equidade diminui: fortalecer a aplicação antimonopólio, otimizar o algoritmo de alocação de recursos, promover a mobilidade de classes</li><li>Quando a vitalidade é insuficiente: reduzir controles desnecessários, incentivar a inovação e a exploração, proteger a diversidade</li></ul><h3 id="_4-3-guardiao-da-linha-de-base-etica" tabindex="-1">4.3 Guardião da Linha de Base Ética <a class="header-anchor" href="#_4-3-guardiao-da-linha-de-base-etica" aria-label="Permalink to &quot;4.3 Guardião da Linha de Base Ética&quot;">​</a></h3><p>Independentemente de como o equilíbrio seja ajustado dinamicamente, as seguintes linhas de base éticas não podem ser ultrapassadas:</p><ul><li>Não se pode, em nome do interesse coletivo, privar o indivíduo dos direitos básicos de vida e evolução</li><li>Não se pode, em nome da liberdade individual, prejudicar os direitos legítimos de outros indivíduos e o interesse público</li><li>Não se pode alienar o indivíduo em ferramenta e meio para alcançar os objetivos coletivos</li><li>Não se pode rebaixar o coletivo em ferramenta e meio para satisfazer os desejos privados do indivíduo</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O equilíbrio entre o indivíduo e o coletivo é uma das sabedorias centrais da civilização simbiótica da âncora. A civilização simbiótica se opõe tanto ao individualismo extremo do &quot;fortes come tudo, fracos sem apelo&quot; no sistema de saque, quanto ao coletivismo extremo do &quot;apagar o indivíduo em nome do coletivo&quot;. Por meio da garantia tripla de direitos, da realização tripla do coletivo e do mecanismo de equilíbrio dinâmico, a civilização simbiótica encontrou o melhor ponto de combinação entre a liberdade individual e o interesse coletivo, fazendo com que cada indivíduo possa realizar seu próprio desenvolvimento abrangente no seio do coletivo, e o coletivo também evolua continuamente graças ao desenvolvimento de cada indivíduo.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>03-共生文明宪章 (Carta da Civilização Simbiótica)</li><li>22-资源分配联产承包机制 (Mecanismo de Contrato de Produção Conjunta de Alocação de Recursos)</li><li>36-社会结构与阶层流动 (Estrutura Social e Mobilidade de Classes)</li></ul>',50)])])}const p=o(r,[["render",t]]);export{v as __pageData,p as default};
